insert into public.jobs (slug, company_id, title, type, work_mode, location, industry, salary_min, salary_max, salary_period, description, responsibilities, requirements, skills, featured, posted_at) values
  ('software-engineer-intern-google',(select id from public.companies where slug='google'),'Software Engineer Intern','Internship','Hybrid','Mountain View, CA','Software',9000,11000,'mo','Spend the summer building features used by billions, mentored by senior Google engineers.','{"Build and ship features in a large codebase","Write tests and participate in code reviews","Collaborate with your team and mentor"}','{"Pursuing a CS or related degree","Solid data structures and algorithms","Experience in one of: Java, C++, Python, Go"}','{"Algorithms","Python","C++","Git"}',true, now() - interval '2 days'),
  ('new-grad-swe-google',(select id from public.companies where slug='google'),'Software Engineer, New Grad','New grad','On-site','Mountain View, CA','Software',130000,180000,'yr','Start your engineering career at Google working on products at planetary scale.','{"Design, build and ship production systems","Collaborate across teams","Grow with mentorship and code review"}','{"BS/MS in CS or equivalent","Strong fundamentals","Internship or project experience"}','{"Java","Distributed Systems","SQL","Git"}',true, now() - interval '1 day'),
  ('ios-engineer-intern-apple',(select id from public.companies where slug='apple'),'iOS Engineer Intern','Internship','On-site','Cupertino, CA','Software',9500,12000,'mo','Build delightful experiences for millions of iPhone users alongside Apple engineers.','{"Develop features in Swift/SwiftUI","Obsess over detail and performance","Partner with design"}','{"Pursuing CS degree","Swift or strong Java/Kotlin","Care about craft"}','{"Swift","SwiftUI","iOS","Git"}',false, now() - interval '5 days'),
  ('data-scientist-new-grad-microsoft',(select id from public.companies where slug='microsoft'),'Data Scientist, New Grad','New grad','Hybrid','Redmond, WA','Data & AI',125000,160000,'yr','Turn product data into insight and models that ship inside Microsoft products.','{"Build models and run experiments","Partner with product and engineering","Communicate insights clearly"}','{"BS/MS in a quantitative field","Strong Python and SQL","ML fundamentals"}','{"Python","SQL","Machine Learning","Azure"}',true, now() - interval '3 days'),
  ('swe-intern-amazon',(select id from public.companies where slug='amazon'),'SDE Intern','Internship','On-site','Seattle, WA','E-commerce',8500,11000,'mo','Own a real project end-to-end on an Amazon team and ship it during your internship.','{"Design and build a service or feature","Operate with ownership","Present your results"}','{"CS student","Strong coding fundamentals","Java, Python or C++"}','{"Java","AWS","Data Structures","Git"}',false, now() - interval '6 days'),
  ('ml-engineer-meta',(select id from public.companies where slug='meta'),'Machine Learning Engineer','Full-time','Hybrid','Menlo Park, CA','Software',160000,230000,'yr','Build ML systems powering ranking and recommendations across Meta''s apps.','{"Develop and deploy ML models in production","Run large-scale experiments","Improve model quality and efficiency"}','{"2+ years ML experience","Strong Python and ML","Experience with large datasets"}','{"Python","PyTorch","Machine Learning","Spark"}',true, now() - interval '2 days'),
  ('backend-engineer-netflix',(select id from public.companies where slug='netflix'),'Backend Engineer','Full-time','Remote','Remote (US)','Software',170000,240000,'yr','Build the resilient services that stream entertainment to the world.','{"Design high-scale backend services","Improve reliability and latency","Own systems end-to-end"}','{"3+ years backend experience","Strong systems design","Java, Kotlin or Go"}','{"Java","Microservices","AWS","Kafka"}',false, now() - interval '4 days'),
  ('ai-research-intern-nvidia',(select id from public.companies where slug='nvidia'),'AI Research Intern','Internship','On-site','Santa Clara, CA','Data & AI',10000,13000,'mo','Work with NVIDIA researchers on the frontier of deep learning and accelerated computing.','{"Prototype and evaluate models","Optimize on GPUs","Publish and present findings"}','{"Pursuing MS/PhD in ML or related","PyTorch or TensorFlow","Strong math"}','{"Python","PyTorch","CUDA","Deep Learning"}',true, now() - interval '5 days'),
  ('software-engineer-stripe',(select id from public.companies where slug='stripe'),'Software Engineer','Full-time','Hybrid','San Francisco, CA','Fintech',160000,220000,'yr','Build the APIs and systems that move money for millions of businesses.','{"Build reliable payments services","Design clean APIs","Care about correctness"}','{"2+ years experience","Strong fundamentals","Ruby, Go or TypeScript"}','{"TypeScript","Go","PostgreSQL","APIs"}',true, now() - interval '1 day'),
  ('product-design-intern-airbnb',(select id from public.companies where slug='airbnb'),'Product Design Intern','Internship','Hybrid','San Francisco, CA','Design',8000,10000,'mo','Design experiences that help guests and hosts belong anywhere.','{"Create wireframes and hi-fi designs","Contribute to the design system","Run usability tests"}','{"Design student with a portfolio","Figma proficiency","Strong eye for interaction"}','{"Figma","UI Design","Prototyping","User Research"}',false, now() - interval '7 days'),
  ('research-engineer-openai',(select id from public.companies where slug='openai'),'Research Engineer','Full-time','On-site','San Francisco, CA','Data & AI',200000,300000,'yr','Build and scale the systems behind frontier AI models.','{"Train and evaluate large models","Build research infrastructure","Collaborate with researchers"}','{"Strong engineering + ML","Python and PyTorch","Large-scale systems"}','{"Python","PyTorch","Distributed Training","CUDA"}',true, now() - interval '2 days'),
  ('new-grad-swe-openai',(select id from public.companies where slug='openai'),'Software Engineer, New Grad','New grad','On-site','San Francisco, CA','Data & AI',180000,250000,'yr','Join OpenAI early in your career and build products used by hundreds of millions.','{"Ship product and platform features","Work across the stack","Learn fast"}','{"BS/MS in CS","Strong fundamentals","Project or internship experience"}','{"Python","TypeScript","React","APIs"}',false, now() - interval '3 days'),
  ('autonomy-intern-tesla',(select id from public.companies where slug='tesla'),'Autonomy Software Intern','Internship','On-site','Austin, TX','Energy',9000,12000,'mo','Work on the software behind Tesla''s self-driving and energy products.','{"Build and test autonomy software","Work with real vehicle data","Ship improvements"}','{"CS/EE student","C++ or Python","Interest in robotics/ML"}','{"C++","Python","Robotics","Machine Learning"}',false, now() - interval '8 days'),
  ('forward-deployed-engineer-salesforce',(select id from public.companies where slug='salesforce'),'Forward Deployed Engineer','Full-time','Remote','Remote (US)','Software',140000,190000,'yr','Help enterprises get the most out of the Salesforce platform.','{"Build solutions on the platform","Work directly with customers","Translate needs into software"}','{"2+ years experience","Full-stack skills","Great communication"}','{"JavaScript","Apex","SQL","APIs"}',false, now() - interval '10 days'),
  ('data-engineer-intern-amazon',(select id from public.companies where slug='amazon'),'Data Engineer Intern','Internship','Hybrid','Seattle, WA','E-commerce',8500,11000,'mo','Build the pipelines that power Amazon analytics and ML.','{"Build and maintain ETL pipelines","Work with Spark and streaming","Improve data quality"}','{"CS/Data student","Python and SQL","Curious about distributed systems"}','{"Python","SQL","Spark","Airflow"}',false, now() - interval '4 days'),
  ('frontend-engineer-airbnb',(select id from public.companies where slug='airbnb'),'Frontend Engineer','Full-time','Hybrid','San Francisco, CA','Software',150000,205000,'yr','Build polished web experiences for the Airbnb community.','{"Ship UI in React + TypeScript","Partner with design and product","Care about performance and accessibility"}','{"2+ years frontend","React and TypeScript","Eye for detail"}','{"React","TypeScript","CSS","GraphQL"}',true, now() - interval '1 day');
